head.script:
scwin.screenId = "jldfil70212";

///////// 1. 변수 및 선언 영역 /////////

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.form = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "btn_EtnExcelUpload", fn: function(){ return (((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))) && typeof (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))).getRowCount === 'function' ? (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))).getRowCount() : (((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))) == null) ? 0 : ((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))).length || 0))) !=0 && !(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList")))).length === 0)); } }, { id: "btn_EtnExcelResultDown", fn: function(){ return (((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))) && typeof (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))).getRowCount === 'function' ? (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))).getRowCount() : (((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))) == null) ? 0 : ((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))).length || 0))) !=0 && !(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "excelCheckList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("excelCheckList")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil70212.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_EtnExcelUpload_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_EtnExcelUpload_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_EtnExcelUpload_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.etnExcelUpload()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70212.btn_EtnExcelUpload_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_EtnExcelResultDown_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_EtnExcelResultDown_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_EtnExcelResultDown_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.etnExcelResultDown()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70212.btn_EtnExcelResultDown_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_closePop_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_closePop_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_closePop_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close_pop()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70212.btn_closePop_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_EtnExcelResultDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_EtnExcelResultDown = async function () {
    const sbmOptions = {
        id: "tx_fn_EtnExcelResultDown",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_EtnExcelResultDownReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil70212.tx_fn_EtnExcelResultDown" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_loadListReq",
        target: "",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil70212.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        {
            const d = $c.util.getComponent("dlt_excelCheckList");
            const a = (res && res.responseJSON && res.responseJSON.body && res.responseJSON.body.content) || [];
            if (!d || !d.setJSON) { console.error('[sdd] 구분자 열 채우기 대상 없음: dlt_excelCheckList'); }
            else { d.setJSON(a.map(function (v) {
                            const p = String(v == null ? '' : (v && v.value !== undefined ? v.value : v)).split("&@!&");
                            return { c0: p[0] || '', c1: p[1] || '', c2: p[2] || '', c3: p[3] || '', c4: p[4] || '' };
                })); }
        }
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.close_pop
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close_pop = function () {
    /* sdd-asis-lifecycle:begin close_pop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.setPageFrameSrc(null, '/jldfil70301/jldfil70301.xml', { method: "searchList", listBzCd: "0" });
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.etnExcelUpload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.etnExcelUpload = function () {
    /* sdd-asis-lifecycle:begin fn_EtnExcelUpload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.setPageFrameSrc($c.win.getFrame(), "/jldfil70211/jldfil70211.xml");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.etnExcelResultDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.etnExcelResultDown = async function () {
    /* sdd-asis-lifecycle:begin fn_EtnExcelResultDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.etnlistResultDownForm || { elements: [] });
    scwin.form.action = '/etn/EtnList.do';
    $c.util.getComponent('dma_EtnExcelResultDownReq').set('method', 'etnExcelResultDownload');
    await scwin.tx_fn_EtnExcelResultDown();
    /* sdd-asis-lifecycle:end */
};
